type counterGroupDisplay struct{ prefix, label string }

var counterGroupDisplays = []counterGroupDisplay{
	{prefix: "semantic.suppressed_anchors.", label: "suppressed_anchors"},
	{prefix: "semantic.code_chunks_pruned.", label: "code_chunks_pruned"},
	{prefix: "semantic.code_plan.kind.", label: "code_plan_kind"},
	{prefix: "semantic.code_plan.granularity.", label: "code_plan_granularity"},
	{prefix: "semantic.code_chunks.kind.", label: "code_embedded_kind"},
	{prefix: "semantic.code_chunks.granularity.", label: "code_embedded_granularity"},
}

func groupedCounter(name MetricName) bool {
	for _, group := range counterGroupDisplays {
		if strings.HasPrefix(string(name), group.prefix) {
			return true
		}
	}
	return false
}

func metricDisplayFor(name MetricName) (metricDisplay, bool) {
	if display, ok := metricDisplays[name]; ok {
		return display, true
	}
	if prefix := strings.TrimSuffix(CodeEmbeddingNeed.pattern, "%s"); strings.HasPrefix(string(name), prefix) {
		label := "need_" + strings.TrimPrefix(string(name), prefix)
		return metricDisplay{windowTotal: label, summaryTotal: label}, true
	}
	if prefix := "codeembed.state."; strings.HasPrefix(string(name), prefix) {
		label := "state_" + strings.TrimPrefix(string(name), prefix)
		return metricDisplay{windowTotal: label, summaryTotal: label}, true
	}
	return metricDisplay{}, false
}
